//! Byte parity against the TypeScript writer (cut gap G18): the golden fixture's three files
//! and a seeded differential corpus, generated by `bun crates/aac-snapshot/tests/generate-fixtures.ts`
//! from the same TS code the golden test pins. Every case rebuilds the sample in Rust and must
//! match the TypeScript bytes exactly.

use aac_snapshot::history::{QuotaHistory, RecentReadings};
use aac_snapshot::js::{stringify, stringify_pretty};
use aac_snapshot::markdown::render_snapshot_markdown;
use aac_snapshot::snapshot::{LongBurnEntry, LongBurnSpan, SampleEvent, build_snapshot_files};
use serde_json::Value;
use std::collections::HashMap;
use std::path::PathBuf;

fn fixtures_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("tests")
        .join("fixtures")
}

fn golden_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("..")
        .join("..")
        .join("tests")
        .join("unit")
        .join("web-server")
        .join("agent-usage-golden")
}

fn load(file: &str) -> Value {
    let text = std::fs::read_to_string(fixtures_dir().join(file)).expect("fixture");
    serde_json::from_str(&text).expect("fixture parse")
}

fn span(value: &Value) -> LongBurnSpan {
    LongBurnSpan {
        span_ms: value["spanMs"].as_i64().expect("spanMs"),
        consumed: value["consumed"].as_f64(),
        rate: value["rate"].as_f64(),
        coverage: value["coverage"].as_f64().expect("coverage"),
    }
}

fn event(value: &Value) -> SampleEvent {
    let long_burn = value["longBurn"].as_array().map(|entries| {
        entries
            .iter()
            .map(|entry| {
                let key = entry[0].as_str().expect("longBurn key").to_owned();
                let burns = &entry[1];
                (
                    key,
                    LongBurnEntry {
                        last7_days: span(&burns["last7Days"]),
                        last30_days: span(&burns["last30Days"]),
                    },
                )
            })
            .collect::<HashMap<String, LongBurnEntry>>()
    });
    SampleEvent {
        accounts: value["accounts"].as_array().expect("accounts").clone(),
        history: if value["history"].is_null() {
            None
        } else {
            Some(QuotaHistory::from_value(&value["history"]))
        },
        sampled_at: value["sampledAt"].as_i64().expect("sampledAt"),
        long_burn,
    }
}

fn ring(samples: &Value) -> RecentReadings {
    let mut ring = RecentReadings::new();
    if let Some(samples) = samples.as_array() {
        for sample in samples {
            ring.add(
                sample["accounts"].as_array().expect("sample accounts"),
                sample["sampledAt"].as_i64().expect("sample time"),
            );
        }
    }
    ring
}

fn sign_in(value: &Value) -> Vec<Value> {
    value.as_array().cloned().unwrap_or_default()
}

fn assert_bytes(case: &str, name: &str, expected: &str, actual: &str) {
    if expected == actual {
        return;
    }
    let expected_bytes = expected.as_bytes();
    let actual_bytes = actual.as_bytes();
    let at = expected_bytes
        .iter()
        .zip(actual_bytes.iter())
        .position(|(a, b)| a != b)
        .unwrap_or(expected_bytes.len().min(actual_bytes.len()));
    let from = at.saturating_sub(60);
    panic!(
        "{case}: {name} differs at byte {at}\n  expected: ...{}...\n  actual:   ...{}...",
        String::from_utf8_lossy(&expected_bytes[from..(from + 120).min(expected_bytes.len())]),
        String::from_utf8_lossy(&actual_bytes[from..(from + 120).min(actual_bytes.len())]),
    );
}

/// The golden fixture: the same inputs the TS golden test drives, against the checked-in goldens.
#[test]
fn golden_files_match_byte_for_byte() {
    let input = load("golden-input.json");
    let sample = event(&input["event"]);
    let readings = ring(&input["recentSamples"]);
    let (snapshot, history) = build_snapshot_files(
        &sample,
        input["refreshSeconds"].as_f64().expect("refreshSeconds"),
        Some(&readings),
        &sign_in(&input["signIn"]),
        if input["signInRenewal"].is_null() {
            None
        } else {
            Some(&input["signInRenewal"])
        },
    );
    let markdown =
        render_snapshot_markdown(&snapshot, input["signInNow"].as_i64().expect("signInNow"));
    let json = format!("{}\n", stringify_pretty(&snapshot));
    let history_text = format!("{}\n", history.to_json());
    // The streamed text is the value's own text.
    assert_eq!(history.to_json(), stringify(&history.value()));
    let read_golden =
        |name: &str| std::fs::read_to_string(golden_dir().join(name)).expect("golden file");
    assert_bytes("golden", "usage.md", &read_golden("usage.md"), &markdown);
    assert_bytes("golden", "usage.json", &read_golden("usage.json"), &json);
    assert_bytes(
        "golden",
        "history.json",
        &read_golden("history.json"),
        &history_text,
    );
}

/// The differential corpus: 60 seeded cases through the same TS writer, byte for byte.
#[test]
fn corpus_matches_the_typescript_writer() {
    let corpus = load("corpus.json");
    let cases = corpus.as_array().expect("corpus array");
    let mut checked = 0;
    for case in cases {
        let seed = case["seed"].as_i64().expect("seed");
        let label = format!("case {seed}");
        let sample = event(&case["event"]);
        let readings = ring(&case["recentSamples"]);
        let (snapshot, history) = build_snapshot_files(
            &sample,
            case["refreshSeconds"].as_f64().expect("refreshSeconds"),
            Some(&readings),
            &sign_in(&case["signIn"]),
            if case["signInRenewal"].is_null() {
                None
            } else {
                Some(&case["signInRenewal"])
            },
        );
        let markdown =
            render_snapshot_markdown(&snapshot, case["signInNow"].as_i64().expect("signInNow"));
        let json = format!("{}\n", stringify_pretty(&snapshot));
        let history_text = format!("{}\n", history.to_json());
        // The streamed text is the value's own text.
        assert_eq!(history.to_json(), stringify(&history.value()));
        assert_bytes(
            &label,
            "usage.json",
            case["expected"]["json"].as_str().expect("json"),
            &json,
        );
        assert_bytes(
            &label,
            "usage.md",
            case["expected"]["markdown"].as_str().expect("markdown"),
            &markdown,
        );
        assert_bytes(
            &label,
            "history.json",
            case["expected"]["history"].as_str().expect("history"),
            &history_text,
        );
        checked += 1;
    }
    assert_eq!(checked, 60);
}
